using NaughtyAttributes;
using UnityEngine;

namespace LittleLeo.Variables;

[CreateAssetMenu(menuName = "Variables References/AnimationCurve Reference")]
public class AnimationCurveReference : ScriptableObject
{
	[Header("Variable")]
	[SerializeField]
	private bool externalSet;

	[SerializeField]
	[HideIf("externalSet")]
	private AnimationCurve value;

	public AnimationCurve Value => value;

	public void SetExternalSet(bool value)
	{
		externalSet = value;
	}

	public void SetValue(AnimationCurve value)
	{
		if (externalSet)
		{
			Debug.LogFormat("Setting AnimationCurve Value to {0}", value);
			this.value = value;
		}
		else
		{
			Debug.Log($"Cannot set {base.name} from external source, because bool externalSet is false");
		}
	}
}
